SELECT *
FROM Product
WHERE Category = 'Gadgets';

SELECT name, price, manufacturer
FROM Product
WHERE category = 'Gadgets';

SELECT name
FROM Product
WHERE LOWER(name) LIKE '%gizmo%';

DROP TABLE IF EXISTS Enrolled;

CREATE TABLE Enrolled (
  student_id VARCHAR(10),
  cid VARCHAR(10),
  grade VARCHAR(2),
  PRIMARY KEY (student_id, cid),
  FOREIGN KEY (student_id) REFERENCES Students(sid)
);

SELECT DISTINCT p.name, p.address
FROM Person AS p
JOIN Company AS c ON p.worksfor = c.name;

SELECT R.A
FROM R, S
WHERE R.A = S.B;

SELECT R.A FROM R, S WHERE R.A = S.A
INTERSECT
SELECT R.A FROM R, T WHERE R.A = T.A;

SELECT R.A FROM R, S WHERE R.A = S.A
UNION
SELECT R.A FROM R, T WHERE R.A = T.A;

SELECT R.A FROM R, S WHERE R.A = S.A
UNION ALL
SELECT R.A FROM R, T WHERE R.A = T.A;

SELECT R.A FROM R, S WHERE R.A = S.A
EXCEPT
SELECT R.A FROM R, T WHERE R.A = T.A;

SELECT DISTINCT c.hq_city
FROM Company AS c
WHERE c.name IN (
  SELECT maker FROM Product WHERE factory_loc = 'US'
)
AND c.name IN (
  SELECT maker FROM Product WHERE factory_loc = 'China'
);

SELECT COUNT(*) AS recent_products
FROM Product
WHERE year > 1995;

SELECT AVG(price) AS toyota_average
FROM Product
WHERE maker = 'Toyota';

SELECT SUM(price * quantity) AS BagelSales
FROM Purchase
WHERE product = 'Bagel';

SELECT p.name, pu.store
FROM Product AS p
JOIN Purchase AS pu ON p.name = pu.product;

SELECT p.name, pu.store
FROM Product AS p
LEFT JOIN Purchase AS pu ON p.name = pu.product;

SELECT DISTINCT R.A
FROM R, S, T
WHERE R.A = S.A OR R.A = T.A;
